// Module geschichten - which Pisolala story comes next (A5, Peter 02.11.).
// No screen, no storage: tested in Node (tests/module/geschichten.test.mjs). Inserted into the app by werkzeug/module.mjs.
//
// Peter, 02.11.: every time a new story, fitting special days (Halloween, Advent, Christmas, birthday).
// The app cannot invent stories (no server; every story needs Peter's approval) - so the stock grows in
// approved batches, and this module picks from it:
//   1. on the child's birthday an unread birthday story, in a theme time an unread story of that theme;
//   2. otherwise the next unread story without an occasion (in list order - stories can be a series);
//   3. when all were read: the one read longest ago (occasion stories only in their time).
//   An occasion story outside its time comes only if there is no other story at all.
// One story per round, like the jokes (the app keeps the round key).
//
// Pisolala: a family character. Never shown, never described – only what happens around Pisolala.
// New stories go in only after a grown-up approved them (approved:true). Excitement: 1 cozy, 2 a bit exciting, 3 adventurous.
// Language (Peter, 30.10.): English; German only in the Deutsch subject. Each story has en and de.
// occasion: 'halloween' | 'advent' | 'christmas' | 'birthday' (optional).

export const STORY_LIST=[
  {id:'halloween-2026', occasion:'halloween', approved:true /* freigegeben von Peter am 30.10.2026 (de); en = freie amerikanische Übersetzung (02.11.) */,
   title:{en:'Pisolala and the Giggling Pumpkins', de:'Pisolala und die kichernden Kürbisse'},
   en:{
    1:"On Halloween night, a warm little breeze drifted through the yard. It smelled like hot cocoa and cinnamon – that's how it always smells when Pisolala is close by. Nobody can see Pisolala. But if you listen really carefully, you can hear a soft giggle in the leaves.\n\nNofretete was already waiting in her pumpkin costume, and Hoppel, her cuddly bunny, was carrying a tiny lantern.\n\n\"Trick or joke?\" the breeze whispered at the first door. The neighbor laughed. \"A joke, please!\" Something rustled: \"What's a ghost's favorite food? Spook-ghetti!\"\n\nA bunch of little pumpkins sat along the fence. Nofretete counted: \"… 36, 37, 38!\" The breeze hummed, \"That's about 40!\" Because 38 is closer to 40 than to 30.\n\nBack home there was hot cocoa. Nofretete fell asleep hugging Hoppel, while outside a soft wind song hummed. \"Good night, Pisolala.\" And somewhere, something giggled: \"Good night.\"",
    2:"On Halloween night, a warm little breeze drifted through the yard. It smelled like hot cocoa and cinnamon – that's how it always smells when Pisolala is close by. Nobody can see Pisolala. But if you listen really carefully, you can hear a soft giggle in the leaves.\n\nNofretete was waiting in her pumpkin costume, and Hoppel was carrying a tiny lantern. \"Trick or joke?\" the breeze whispered at the first door. \"What's a ghost's favorite food? Spook-ghetti!\" The neighbor laughed out loud.\n\nThen the path got dark. Something creaked behind the fence. A long shadow slid across the stones. Nofretete stopped. \"I'm a little bit scared.\" Right then, it got very warm next to her. \"Take a deep breath,\" something whispered, \"and picture the little lantern in your heart.\"\n\nNofretete breathed in and out. Hoppel's lantern glowed brighter – and the shadow was … a cat in a pumpkin hat! It meowed and ran off. Everybody burst out laughing.\n\nBack home there was hot cocoa. \"Good night, Pisolala.\" And somewhere, something giggled: \"Good night.\""
   },
   de:{
    1:'Am Halloween-Abend wehte ein warmer, kleiner Wind durch den Garten. Er roch nach Kakao und Zimt – so riecht es immer, wenn Pisolala in der Nähe ist. Sehen kann Pisolala niemand. Aber wer genau hinhört, hört ein leises Kichern zwischen den Blättern.\n\nNofretete wartete schon in ihrem Kürbiskostüm, und Hoppel, der Kuschelhase, trug eine winzige Laterne.\n\n„Süßes oder Witz?“, flüsterte der Wind an der ersten Tür. Die Nachbarin lachte: „Einen Witz, bitte!“ Da raschelte es: „Was essen Gespenster am liebsten? Spukhetti!“\n\nAm Zaun standen kleine Kürbisse. Nofretete zählte: „… 36, 37, 38!“ Der Wind summte: „Ungefähr 40!“ Denn 38 liegt näher an 40 als an 30.\n\nZu Hause gab es Kakao. Nofretete schlief mit Hoppel im Arm ein, und draußen summte ein leises Windlied. „Gute Nacht, Pisolala.“ Und irgendwo kicherte es: „Gute Nacht.“',
    2:'Am Halloween-Abend wehte ein warmer, kleiner Wind durch den Garten. Er roch nach Kakao und Zimt – so riecht es immer, wenn Pisolala in der Nähe ist. Sehen kann Pisolala niemand. Aber wer genau hinhört, hört ein leises Kichern zwischen den Blättern.\n\nNofretete wartete in ihrem Kürbiskostüm, und Hoppel trug eine winzige Laterne. „Süßes oder Witz?“, flüsterte der Wind an der ersten Tür. „Was essen Gespenster am liebsten? Spukhetti!“ Die Nachbarin lachte laut.\n\nDann wurde der Weg dunkel. Hinter dem Zaun knarrte etwas. Ein langer Schatten huschte über die Steine. Nofretete blieb stehen. „Ich hab ein bisschen Angst.“ Da wurde es neben ihr ganz warm. „Atme tief ein“, flüsterte es, „und stell dir die kleine Laterne in deinem Herzen vor.“\n\nNofretete atmete ein und aus. Hoppels Laterne leuchtete heller – und der Schatten war … eine Katze mit einem Kürbishut! Sie miaute und lief davon. Alle mussten lachen.\n\nZu Hause gab es Kakao. „Gute Nacht, Pisolala.“ Und irgendwo kicherte es: „Gute Nacht.“'
   }},
  {id:'advent-erstes-tuerchen', occasion:'advent', approved:true /* freigegeben von Peter am 02.11.2026, alle drei Stufen; en = freie amerikanische Übersetzung */,
   title:{en:"The First Little Door", de:"Das erste Türchen"},
   en:{
    1:"On the first morning of December, the window was covered in frost. Right in the middle, someone had drawn a tiny star – super delicate, like it was traced with a fingertip. Nobody in the house had done it.\n\nNofretete pressed her nose against the glass. Suddenly it smelled like hot cocoa and cinnamon. \"Pisolala?\" she whispered. A soft giggle answered.\n\nThe Advent calendar had 24 little doors. Nofretete opened the first one. Inside was a note: \"Today, do something nice for someone.\"\n\n\"24 doors, and one is open – so 23 are left,\" Nofretete figured. The breeze hummed at the window, like it agreed.\n\nAll day long she thought about it. That evening, she drew Mom a star, just like the one in the frost. Mom loved it so much she stuck it on the fridge.\n\nThat night, a warm little breeze blew outside. And a second star appeared on the window.",
    2:"On the first morning of December, someone had drawn a tiny star in the frost on the window. Nofretete couldn't wait to open the first door of her Advent calendar – but the calendar was gone! Only an empty nail was sticking out of the wall.\n\nSomething rustled behind the curtain. A shadow moved, big and scruffy. Nofretete squeezed Hoppel tight. \"Who's there?\"\n\nThen it got warm beside her, and it smelled like hot cocoa and cinnamon. \"Take a closer look,\" something whispered. Nofretete pulled back the curtain – and there sat Rocco the raccoon, with the calendar in his lap.\n\n\"I just wanted to see how many doors there are,\" he said, a little embarrassed. \"I'm not very good at waiting.\"\n\nThey counted together: 24 doors. Nofretete opened the first one. Inside was a note: \"Today, do something nice for someone.\" 24 minus one – 23 to go.\n\nNofretete gave Rocco the very first cookie of Advent. Rocco beamed. And a second star appeared on the window.",
    3:"On the first morning of December, there was a star drawn in the frost on the window. And outside in the snow, a trail of footprints led away from the house – footprints that didn't belong to anyone.\n\nNofretete pulled on her boots and hat, grabbed Hoppel, and followed them. The trail went across the yard, over the meadow, all the way to the creek at the edge of the woods. The creek was frozen. \"Is the ice thick enough?\" Nofretete asked.\n\nA warm breeze brushed over the ice. \"Take the bridge,\" it whispered. A little farther down was a narrow wooden footbridge, white with frost. Nofretete crossed very slowly, one step at a time, holding on to the railing.\n\nOn the other side, under a pine tree, a tiny light was flickering. It was a little star child. \"I fell down last night,\" it squeaked, \"and I can't find my way home.\"\n\nTogether they climbed the hill. At the top, the breeze blew very gently from below – and the star child floated up, higher and higher, until it disappeared among the other stars.\n\nBack home, Nofretete opened the first door. 24 doors, one open – 23 to go. That evening, a little star above the hill blinked three times in a row. In star language, that means: thank you."
   },
   de:{
    1:"Am ersten Dezembermorgen war das Fenster ganz weiß vom Frost. Mitten im Frost war ein kleiner Stern gemalt – ganz fein, als hätte jemand mit dem Finger gezeichnet. Niemand im Haus war es gewesen.\n\nNofretete drückte die Nase an die Scheibe. Da roch es plötzlich nach Kakao und Zimt. „Pisolala?“, flüsterte sie. Ein leises Kichern antwortete.\n\nAm Adventskalender hingen 24 Türchen. Nofretete öffnete das erste. Darin lag ein Zettel: „Heute darfst du jemandem eine Freude machen.“\n\n„24 Türchen, eins ist offen – dann sind noch 23 übrig“, rechnete Nofretete. Der Wind summte zustimmend am Fenster.\n\nDen ganzen Tag überlegte sie. Am Abend malte sie Mama einen Stern, genau so einen wie im Frost. Mama freute sich so sehr, dass sie ihn an den Kühlschrank hängte.\n\nIn der Nacht wehte draußen ein warmer, kleiner Wind. Und auf dem Fenster erschien ein zweiter Stern.",
    2:"Am ersten Dezembermorgen war ein kleiner Stern in den Frost am Fenster gemalt. Nofretete freute sich auf das erste Türchen – aber der Adventskalender war weg! Nur ein leerer Nagel steckte in der Wand.\n\nHinter dem Vorhang raschelte es. Ein Schatten bewegte sich, groß und struppig. Nofretete hielt Hoppel ganz fest. „Wer ist da?“\n\nDa wurde es neben ihr warm, und es roch nach Kakao und Zimt. „Schau mal genau hin“, flüsterte es. Nofretete zog den Vorhang zur Seite – und da saß Rocco, der Waschbär, mit dem Kalender auf dem Schoß.\n\n„Ich wollte nur sehen, wie viele Türchen es sind“, sagte er verlegen. „Ich kann nämlich nicht so gut warten.“\n\nSie zählten zusammen: 24 Türchen. Nofretete öffnete das erste, darin lag ein Zettel: „Heute darfst du jemandem eine Freude machen.“ 24 minus eins – noch 23 übrig.\n\nNofretete schenkte Rocco das erste Plätzchen des Advents. Rocco strahlte. Und auf dem Fenster erschien ein zweiter Stern.",
    3:"Am ersten Dezembermorgen war ein Stern in den Frost am Fenster gemalt. Und draußen im Schnee führte eine Spur vom Haus weg – eine Spur, die zu niemandem gehörte.\n\nNofretete zog Stiefel und Mütze an, nahm Hoppel und folgte ihr. Die Spur führte durch den Garten, über die Wiese bis zum Bach am Waldrand. Der Bach war zugefroren. „Ist das Eis dick genug?“, fragte Nofretete.\n\nEin warmer Wind strich über das Eis. „Nimm den Steg“, flüsterte es. Ein Stück weiter lag ein schmaler Holzsteg, weiß vom Frost. Nofretete ging ganz langsam, Schritt für Schritt, und hielt sich am Geländer fest.\n\nAuf der anderen Seite, unter einer Tanne, flackerte ein winziges Licht. Es war ein kleines Sternenkind. „Ich bin heute Nacht heruntergefallen“, piepste es, „und finde nicht mehr nach Hause.“\n\nGemeinsam stiegen sie auf den Hügel. Oben blies der Wind ganz sanft von unten – und das Sternenkind schwebte hinauf, höher und höher, bis es zwischen den anderen Sternen verschwand.\n\nZu Hause öffnete Nofretete das erste Türchen. 24 Türchen, eins offen – noch 23. Am Abend blinkte über dem Hügel ein kleiner Stern, dreimal hintereinander. Das heißt in der Sternensprache: Danke."
   }},
  {id:'advent-roccos-wunschzettel', occasion:'advent', approved:true /* freigegeben von Peter am 02.11.2026, alle drei Stufen; en = freie amerikanische Übersetzung */,
   title:{en:"Rocco's Wish List", de:"Roccos Wunschzettel"},
   en:{
    1:"Rocco the raccoon came racing over, totally out of breath. \"My wish list is gone! The wind snatched it right out of my paw!\"\n\nNofretete and Hoppel helped him look. It wasn't under the bench, and it wasn't in the leaves. Then it got dark, and the woods started making strange noises. Rocco stopped. \"I think I'm a little bit scared.\"\n\nRight then, it got very warm around them. \"Take a deep breath,\" something whispered, \"and picture the little lantern in your heart.\" They breathed in and out – and up in the pine tree, something rustled. There was the list, safe between two branches.\n\nA warm puff of wind nudged it down, very gently, right into Rocco's paws.\n\n\"So what are you wishing for?\" Nofretete asked. Rocco blushed a little. \"That we all bake cookies together.\"\n\nAnd somewhere up in the pine tree, something giggled very softly.",
    2:"Rocco came racing over, totally out of breath. \"My wish list is gone! The wind snatched it right out of my paw!\"\n\nThey spotted it just in time – flying over the meadow and down to the pond. It landed on a lily pad, right in the middle of the water.\n\nLuckily, there were stepping stones going across. Nofretete stepped onto the first one, then the second. The third one wobbled. \"I don't want to go any farther,\" she said quietly.\n\nRight then, it got very warm next to her. \"Take a deep breath,\" something whispered, \"and picture the little lantern in your heart.\" Nofretete breathed in and out. Then she put her foot down very carefully in the middle of the stone – and it held.\n\nA warm breeze slowly pushed the lily pad over to her. She grabbed the list. It was only a tiny bit wet.\n\n\"So what are you wishing for?\" she asked Rocco back on the shore. Rocco blushed. \"That we all bake cookies together.\" And over the pond, something giggled very softly.",
    3:"Rocco came racing over, totally out of breath. \"My wish list is gone! The wind blew it all the way up to the old tower on the hill!\"\n\nNofretete, Hoppel, and Rocco hiked up the hill. The tower was old, and the door squeaked. Inside, a spiral staircase wound upward, and it was pretty dark.\n\nEvery step creaked. Suddenly something up top called out: \"Hoo-hoo!\" Rocco jumped right into Nofretete's arms. \"I'm scared,\" he whispered.\n\nThen it got warm all around them, and the stairs got a tiny bit brighter, as if a lantern were coming along. \"Take a deep breath,\" something whispered. \"Sometimes when someone calls out, they just want to say something.\"\n\nUp in the window sat an owl. And in her nest was – the wish list. \"It flew right to me,\" the owl said kindly. \"I kept it safe for you.\"\n\nRocco said thank you three times. On the way home, Nofretete asked, \"So what are you wishing for, anyway?\" \"That we all bake cookies together,\" Rocco said. \"And I'm inviting the owl, too.\" Up at the tower, something giggled happily."
   },
   de:{
    1:"Rocco, der Waschbär, kam ganz aufgeregt angesaust. „Mein Wunschzettel ist weg! Der Wind hat ihn mir aus der Pfote gerissen!“\n\nNofretete und Hoppel halfen beim Suchen. Unter der Bank war er nicht, und auch nicht im Laub. Dann wurde es dunkel, und der Wald machte seltsame Geräusche. Rocco blieb stehen. „Ich glaube, ich hab ein bisschen Angst.“\n\nDa wurde es neben ihnen ganz warm. „Atmet tief ein“, flüsterte es, „und stellt euch die kleine Laterne im Herzen vor.“ Sie atmeten ein und aus – und oben in der Tanne raschelte es. Da hing der Zettel, sicher zwischen zwei Zweigen.\n\nEin warmer Windstoß schob ihn ganz sanft herunter, direkt in Roccos Pfoten.\n\n„Was wünschst du dir denn?“, fragte Nofretete. Rocco wurde ein bisschen rot. „Dass wir alle zusammen Plätzchen backen.“\n\nUnd irgendwo in der Tanne kicherte es ganz leise.",
    2:"Rocco kam ganz aufgeregt angesaust. „Mein Wunschzettel ist weg! Der Wind hat ihn mir aus der Pfote gerissen!“\n\nSie sahen ihn gerade noch fliegen – über die Wiese, hinunter zum Teich. Dort landete er auf einem Seerosenblatt, mitten auf dem Wasser.\n\nZum Glück führten Trittsteine hinüber. Nofretete stieg auf den ersten, dann auf den zweiten. Der dritte wackelte. „Ich trau mich nicht weiter“, sagte sie leise.\n\nDa wurde es neben ihr ganz warm. „Atme tief ein“, flüsterte es, „und stell dir die kleine Laterne in deinem Herzen vor.“ Nofretete atmete ein und aus. Dann setzte sie den Fuß ganz vorsichtig in die Mitte des Steins – und er hielt.\n\nEin warmer Windstoß schob das Seerosenblatt langsam zu ihr herüber. Sie nahm den Zettel, er war nur ein bisschen feucht.\n\n„Was wünschst du dir denn?“, fragte sie Rocco am Ufer. Rocco wurde rot. „Dass wir alle zusammen Plätzchen backen.“ Und über dem Teich kicherte es ganz leise.",
    3:"Rocco kam ganz aufgeregt angesaust. „Mein Wunschzettel ist weg! Der Wind hat ihn bis hinauf zum alten Turm auf dem Hügel geweht!“\n\nNofretete, Hoppel und Rocco stiegen den Hügel hinauf. Der Turm war alt, und die Tür quietschte. Innen führte eine Wendeltreppe nach oben, und es war ziemlich dunkel.\n\nBei jeder Stufe knarrte das Holz. Plötzlich rief oben etwas: „Huhuu!“ Rocco sprang vor Schreck in Nofretetes Arme. „Ich hab Angst“, flüsterte er.\n\nDa wurde es warm um sie herum, und die Treppe wurde ein kleines bisschen heller, als würde eine Laterne mitgehen. „Atmet tief ein“, flüsterte es. „Wer ruft, will vielleicht nur etwas sagen.“\n\nOben im Fenster saß eine Eule. In ihrem Nest lag – der Wunschzettel. „Der ist mir zugeflogen“, sagte die Eule freundlich. „Ich habe gut auf ihn aufgepasst.“\n\nRocco bedankte sich dreimal. Auf dem Heimweg fragte Nofretete: „Was wünschst du dir eigentlich?“ – „Dass wir alle zusammen Plätzchen backen“, sagte Rocco. „Und die Eule lade ich auch ein.“ Oben am Turm kicherte es zufrieden."
   }},
  {id:'advent-plaetzchen-mumifius', occasion:'advent', approved:true /* freigegeben von Peter am 02.11.2026, alle drei Stufen; en = freie amerikanische Übersetzung */,
   title:{en:"Baking Cookies with Mumifius", de:"Plätzchen mit Mumifius"},
   en:{
    1:"Mumifius the Third, the ticklish mummy, wanted to bake cookies for the very first time. \"But I don't know how,\" he said.\n\nNofretete grabbed a piece of paper. \"Let's write instructions! First, measure the flour. Next, mix in the butter and sugar. Then, roll out the dough. Finally, cut out stars.\"\n\nWhile they were measuring the flour, a little gust of wind blew through the kitchen. A white cloud puffed up – and landed right on Mumifius. \"Hee-hee, that tickles!\" he squealed, laughing so hard his wrappings wiggled.\n\nThe kitchen smelled like cocoa and cinnamon, even though there wasn't any cinnamon in the dough. Nofretete knew exactly who wanted to help bake.\n\nIn the end there were twelve golden stars on the cookie sheet. Eleven for their friends, and one for the windowsill – for someone you can't see.\n\nThe next morning, the star on the windowsill was gone. All that was left were a few crumbs, and a very soft giggle.",
    2:"Mumifius the Third, the ticklish mummy, wanted to bake cookies for the very first time. Nofretete had already written down the instructions and put them on the table.\n\nBut when she opened the window, a gust of wind blew in – and the instructions flew right out into the snow! \"Oh no,\" cried Mumifius. \"Now we don't know how to do it!\"\n\nNofretete thought for a moment. \"Yes, we do. We wrote them ourselves. We just have to remember the order.\"\n\n\"First, measure the flour,\" she said. \"Next, mix in the butter and sugar,\" Mumifius remembered. \"Then, roll out the dough. Finally, cut out stars!\"\n\nWhile they were measuring the flour, there was another puff of wind – and a white cloud landed right on Mumifius. \"Hee-hee, that tickles!\"\n\nIn the end there were twelve golden stars on the cookie sheet. And outside on the windowsill lay the instructions, neatly folded. Someone had brought them back – and giggled softly while doing it.",
    3:"Mumifius the Third wanted to bake cookies. But the flour jar was empty! \"The store in town is closing soon,\" said Nofretete. \"We have to hurry!\"\n\nThey hopped on the big sled: Nofretete in front, Hoppel in the middle, Mumifius in the back. A warm breeze gave them a push from behind, and off they went down the hill.\n\nThe sled went faster and faster. \"Brake!\" yelled Nofretete, digging her boots into the snow. The sled slowed down and stopped right in front of the store. In snow, you can brake with your feet – on ice, you'd slide a lot farther.\n\nThen Mumifius noticed that one of his wrappings had gotten caught on the runner and unrolled about ten feet! \"Hee-hee, that tickles!\" he squealed while Nofretete wrapped him back up.\n\nThe lady at the store had already turned off the lights. But when she saw the three of them, she laughed and gave them the very last bag of flour.\n\nBack home, they wrote down the instructions: First, measure the flour. Next, the butter and sugar. Then, roll it out. Finally, cut out stars. One star went on the windowsill. By morning it was gone – just a few crumbs were left, and a very soft giggle."
   },
   de:{
    1:"Mumifius der Dritte, die kitzelige Mumie, wollte zum ersten Mal Plätzchen backen. „Ich weiß aber nicht, wie das geht“, sagte er.\n\nNofretete holte einen Zettel. „Wir schreiben eine Anleitung! Als Erstes wiegt man das Mehl ab. Als Nächstes rührt man Butter und Zucker hinein. Danach rollt man den Teig aus. Zum Schluss sticht man Sterne aus.“\n\nBeim Mehlabwiegen pustete ein kleiner Windstoß durch die Küche. Eine weiße Wolke flog hoch – und landete genau auf Mumifius. „Hihi, das kitzelt!“, quietschte er und musste so lachen, dass seine Binden wackelten.\n\nEs roch nach Kakao und Zimt, obwohl gar kein Zimt im Teig war. Nofretete wusste genau, wer da mitbacken wollte.\n\nAm Ende lagen zwölf goldene Sterne auf dem Blech. Elf für die Freunde und einer fürs Fensterbrett – für jemanden, den man nicht sehen kann.\n\nAm nächsten Morgen war der Stern auf dem Fensterbrett weg. Nur ein paar Krümel lagen noch da, und ein ganz leises Kichern.",
    2:"Mumifius der Dritte, die kitzelige Mumie, wollte zum ersten Mal Plätzchen backen. Nofretete hatte die Anleitung schon aufgeschrieben und auf den Tisch gelegt.\n\nDoch als sie das Fenster öffnete, wehte ein Windstoß herein – und die Anleitung flog hinaus in den Schnee! „Oh nein“, rief Mumifius. „Jetzt wissen wir nicht mehr, wie es geht!“\n\nNofretete überlegte. „Doch. Wir haben sie selbst geschrieben. Wir müssen uns nur an die Reihenfolge erinnern.“\n\n„Als Erstes wiegt man das Mehl ab“, sagte sie. „Als Nächstes rührt man Butter und Zucker hinein“, erinnerte sich Mumifius. „Danach rollt man den Teig aus. Zum Schluss sticht man Sterne aus!“\n\nBeim Mehlabwiegen pustete es wieder – und eine weiße Wolke landete genau auf Mumifius. „Hihi, das kitzelt!“\n\nAm Ende lagen zwölf goldene Sterne auf dem Blech. Und draußen auf dem Fensterbrett lag die Anleitung, sauber gefaltet. Jemand hatte sie zurückgebracht und dabei leise gekichert.",
    3:"Mumifius der Dritte wollte Plätzchen backen. Aber die Mehldose war leer! „Der Laden im Dorf schließt gleich“, rief Nofretete. „Wir müssen uns beeilen!“\n\nSie setzten sich auf den großen Schlitten: Nofretete vorne, Hoppel in der Mitte, Mumifius hinten. Ein warmer Wind schob von hinten an, und los ging es den Hügel hinunter.\n\nDer Schlitten wurde schneller und schneller. „Bremsen!“, rief Nofretete und drückte die Stiefel in den Schnee. Der Schlitten wurde langsamer und blieb genau vor dem Laden stehen. Im Schnee bremst man mit den Füßen – auf Eis würde man viel weiter rutschen.\n\nDoch dann merkte Mumifius: Eine seiner Binden hatte sich in der Kufe verfangen und war meterlang abgewickelt! „Hihi, das kitzelt!“, quietschte er, als Nofretete ihn wieder einwickelte.\n\nDie Verkäuferin hatte schon das Licht ausgemacht. Aber als sie die drei sah, lachte sie und gab ihnen die letzte Tüte Mehl.\n\nZu Hause schrieben sie die Anleitung auf: Als Erstes Mehl abwiegen, als Nächstes Butter und Zucker, danach ausrollen, zum Schluss Sterne ausstechen. Ein Stern kam aufs Fensterbrett. Am Morgen war er weg – nur ein paar Krümel lagen noch da, und ein ganz leises Kichern."
   }},
  {id:'advent-fuchs-im-schnee', occasion:'advent', approved:true /* freigegeben von Peter am 02.11.2026, alle drei Stufen; en = freie amerikanische Übersetzung */,
   title:{en:"The Fox in the Snow", de:"Der Fuchs im Schnee"},
   en:{
    1:"It had snowed. Out in the yard sat the fox, all alone, looking up at the bright windows.\n\n\"He looks sad,\" said Nofretete. She pulled on her boots and took Hoppel with her. Outside, the snow crunched. A warm breeze blew next to her, and a trail appeared in the snow – a trail that didn't belong to anyone.\n\nThe fox didn't say anything. Nofretete didn't say anything either. She just sat down next to him. Sometimes that helps more than a lot of words.\n\nAfter a while, the fox said quietly, \"Everybody's inside having fun. Nobody even notices me.\"\n\n\"I notice you,\" said Nofretete. And the warm breeze wrapped around the two of them like a blanket.\n\nShe gave the fox a star cookie. For the first time that evening, the fox smiled.\n\nWhen Nofretete was back in bed, she looked out one more time. Down in the snow, two trails sat side by side: the fox's, and one that didn't belong to anyone.",
    2:"It had snowed. That evening, Nofretete had seen the fox in the yard, all alone. But when she went out with a cookie, he was gone.\n\nHis tracks led to the hedge. It was dark there, and the branches cracked. Nofretete stopped. Hoppel was shaking in her arms – or was it her?\n\nA warm breeze settled around her shoulders. \"Listen closely,\" it whispered. A soft whimper was coming from the hedge.\n\nThe fox was stuck. His bushy tail had gotten tangled in the branches. He wasn't hurt, but he couldn't get loose by himself.\n\nVery carefully, Nofretete bent the branches aside, one by one. Then his tail was free. The fox shook himself so hard the snow went flying.\n\n\"Thank you,\" he said quietly. \"I thought nobody noticed me.\" \"I notice you,\" said Nofretete, and gave him the cookie. Later, down in the snow, two trails sat side by side: the fox's, and one that didn't belong to anyone.",
    3:"It was snowing so hard you could barely see your own hand. Then there was a tap on the window: the fox was standing outside, totally out of breath. \"I can't find my den,\" he said. \"The snow has covered up every path, and my kids are waiting for me.\"\n\nNofretete bundled up, grabbed Hoppel and a lantern. Outside, the wind was howling. But next to her blew a different wind – a warm one that didn't push her around, but stayed by her side.\n\nThey trudged across the white meadow. Everything looked the same. \"Which way?\" Nofretete asked. Then her lantern suddenly glowed brighter – but only when she pointed it left, toward the woods. So they followed the light.\n\nAt the edge of the woods stood an old oak tree. Under its roots was a hole, almost completely snowed in. A soft whimpering came from inside. \"That's it!\" cried the fox.\n\nTogether they scooped the snow away with their hands until the entrance was clear. Three little fox kits tumbled out and snuggled up to their dad.\n\nOn the way home, the storm was over and the stars came out. In bed, Nofretete looked out one more time. Two trails led back to the house: her own, and one that didn't belong to anyone."
   },
   de:{
    1:"Es hatte geschneit. Im Garten saß der Fuchs, ganz allein, und schaute zu den hellen Fenstern hinauf.\n\n„Der sieht traurig aus“, sagte Nofretete. Sie zog die Stiefel an und nahm Hoppel mit. Draußen knirschte der Schnee. Neben ihr wehte ein warmer Wind, und eine Spur erschien im Schnee – eine Spur, die zu niemandem gehörte.\n\nDer Fuchs sagte nichts. Nofretete sagte auch nichts. Sie setzte sich einfach neben ihn. Manchmal hilft das mehr als viele Worte.\n\nNach einer Weile sagte der Fuchs leise: „Alle sind drinnen und feiern. Mich sieht keiner.“\n\n„Ich sehe dich“, sagte Nofretete. Und der warme Wind legte sich um sie beide wie eine Decke.\n\nSie gab dem Fuchs einen Plätzchenstern. Der Fuchs lächelte zum ersten Mal an diesem Abend.\n\nAls Nofretete wieder im Bett lag, schaute sie noch einmal hinaus. Unten im Schnee saßen zwei Spuren nebeneinander: die vom Fuchs und eine, die zu niemandem gehörte.",
    2:"Es hatte geschneit. Am Abend hatte Nofretete den Fuchs im Garten gesehen, ganz allein. Aber als sie mit einem Plätzchen hinausging, war er verschwunden.\n\nSeine Spuren führten zur Hecke. Dort war es dunkel, und es knackte in den Zweigen. Nofretete blieb stehen. Hoppel zitterte in ihrem Arm – oder war sie es selbst?\n\nEin warmer Wind legte sich um ihre Schultern. „Hör genau hin“, flüsterte es. Aus der Hecke kam ein leises Fiepen.\n\nDer Fuchs saß dort fest. Sein buschiger Schwanz hatte sich in den Zweigen verheddert. Wehgetan hatte er sich nicht, aber er kam allein nicht los.\n\nGanz vorsichtig bog Nofretete die Zweige zur Seite, einen nach dem anderen. Dann war der Schwanz frei. Der Fuchs schüttelte sich, dass der Schnee flog.\n\n„Danke“, sagte er leise. „Ich dachte, mich sieht keiner.“ – „Ich sehe dich“, sagte Nofretete und gab ihm das Plätzchen. Später lagen unten im Schnee zwei Spuren nebeneinander: die vom Fuchs und eine, die zu niemandem gehörte.",
    3:"Es schneite so sehr, dass man kaum die Hand vor Augen sah. Da klopfte es am Fenster: Der Fuchs stand draußen, ganz außer Atem. „Ich finde meinen Bau nicht mehr“, sagte er. „Der Schnee hat alle Wege zugedeckt, und meine Kinder warten auf mich.“\n\nNofretete zog sich warm an, nahm Hoppel und eine Laterne. Draußen heulte der Wind. Doch neben ihr wehte ein anderer Wind – ein warmer, der sie nicht schubste, sondern begleitete.\n\nSie stapften über die weiße Wiese. Alles sah gleich aus. „Wohin jetzt?“, fragte Nofretete. Da leuchtete ihre Laterne plötzlich heller, aber nur, wenn sie nach links zum Wald zeigte. Sie folgten dem Licht.\n\nAm Waldrand stand eine alte Eiche. Unter ihren Wurzeln war ein Loch, fast ganz zugeschneit. Von drinnen kam ein leises Fiepen. „Da ist er!“, rief der Fuchs.\n\nZusammen schaufelten sie den Schnee mit den Händen weg, bis der Eingang frei war. Drei kleine Füchse purzelten heraus und kuschelten sich an ihren Papa.\n\nAuf dem Heimweg war der Sturm vorbei, und die Sterne kamen heraus. Im Bett schaute Nofretete noch einmal hinaus. Im Schnee führten zwei Spuren zum Haus zurück: ihre eigene und eine, die zu niemandem gehörte."
   }},
  {id:'weihnachten-warten', occasion:'christmas', approved:true /* freigegeben von Peter am 02.11.2026, alle drei Stufen; en = freie amerikanische Übersetzung */,
   title:{en:"Waiting Is Hard", de:"Warten ist schwer"},
   en:{
    1:"Christmas Eve was taking longer than ever. Nofretete had already checked the clock three times, and it still wasn't evening.\n\nSomeone else couldn't wait either. The ornaments on the tree jingled softly, even though nobody touched them, and the tinsel swayed back and forth. \"Pisolala, you can't wait either, can you?\" Nofretete laughed.\n\nThen she remembered something Morvandel once said: \"Waiting is like hot cocoa. If you drink it too fast, you burn your tongue. If you wait, it's just right.\"\n\nSo they played waiting games. They counted the ornaments on the tree: 37. \"About 40,\" the breeze hummed.\n\nThen it got dark outside. At the very top of the tree, the star began to glow, even though nobody had turned on the lights yet.\n\nAnd down by the tree, a little bell rang. It was time.",
    2:"Christmas Eve was taking longer than ever. And then, right before it was time for presents, Mom called out, \"Where's the little bell? We can't start without the bell!\"\n\nEverybody looked. It wasn't under the tree, and it wasn't on the shelf. Nofretete looked under the couch. It was dark under there, and way in the back something sparkled – two little shiny dots!\n\nNofretete jumped back. Were those eyes? Then suddenly it smelled like cocoa and cinnamon, and a tiny light glowed under the couch.\n\nThey weren't eyes. They were two ornaments that had rolled off the tree. And between them lay Hoppel – with the bell stuck in his ear! \"Hoppel, I guess you couldn't wait either,\" Nofretete laughed.\n\nShe carried the bell to the tree. At the very top, the star began to glow, even though nobody had turned on the lights yet.\n\nThen the bell rang, bright and clear. It was time.",
    3:"Christmas Eve. It was finally dark, and it was almost time for presents. Then – click! – all the lights in the house went out. Even the lights on the tree went dark.\n\n\"Power outage,\" said Dad. \"That could take a while.\" Nofretete held Hoppel tight. It had never been this dark at home before.\n\nThen it smelled like cocoa and cinnamon. At the very top of the tree, the star began to glow, faintly at first, then brighter and brighter – even though there was no power. Its light reached just far enough to find the candles on the table.\n\nDad lit the candles. Suddenly the room was golden and warm, much nicer than with lamps. \"This is how people used to celebrate Christmas,\" said Mom.\n\nThey sang \"Silent Night,\" and the wind hummed along through the chimney. Outside, the snow glowed in the moonlight.\n\nWhen the song was over, the lights came back on. But everyone wanted to keep the candles burning a little longer. And down by the tree, a little bell rang. It was time."
   },
   de:{
    1:"Heiligabend dauerte heute so lange wie noch nie. Nofretete hatte schon dreimal auf die Uhr geschaut, und es war immer noch nicht Abend.\n\nAuch jemand anderes wartete ungeduldig. Die Christbaumkugeln klirrten leise, obwohl niemand sie berührte, und der Lametta-Faden wehte hin und her. „Pisolala, du kannst auch nicht warten, oder?“, lachte Nofretete.\n\nDa fiel ihr ein, was Morvandel einmal gesagt hatte: „Warten ist wie Kakao. Wenn man ihn zu schnell trinkt, verbrennt man sich. Wenn man wartet, wird er genau richtig.“\n\nAlso spielten sie Warte-Spiele. Sie zählten die Kugeln am Baum: 37. „Ungefähr 40“, summte der Wind.\n\nDann wurde es draußen dunkel. Ganz oben am Baum begann der Stern zu leuchten, obwohl noch niemand die Lichter angemacht hatte.\n\nUnd unten am Baum klingelte eine kleine Glocke. Es war Zeit.",
    2:"Heiligabend dauerte heute so lange wie noch nie. Und dann, kurz vor der Bescherung, rief Mama: „Wo ist denn das Glöckchen? Ohne Glöckchen geht es nicht los!“\n\nAlle suchten. Unter dem Baum war es nicht, auf dem Regal auch nicht. Nofretete schaute unter das Sofa. Dort war es dunkel, und ganz hinten funkelte etwas – zwei kleine glänzende Punkte!\n\nNofretete zuckte zurück. Waren das Augen? Da roch es plötzlich nach Kakao und Zimt, und ein kleines Licht glomm unter dem Sofa auf.\n\nEs waren keine Augen. Es waren zwei Christbaumkugeln, die heruntergerollt waren. Und dazwischen lag Hoppel – mit dem Glöckchen im Ohr! „Hoppel, du wolltest es wohl auch nicht abwarten“, lachte Nofretete.\n\nSie trug das Glöckchen zum Baum. Ganz oben begann der Stern zu leuchten, obwohl noch niemand die Lichter angemacht hatte.\n\nDann klingelte es hell und klar. Es war Zeit.",
    3:"Heiligabend. Endlich war es dunkel, und gleich sollte die Bescherung beginnen. Da machte es „klick“ – und im ganzen Haus gingen die Lichter aus. Auch die Lichterkette am Baum war dunkel.\n\n„Stromausfall“, sagte Papa. „Das kann dauern.“ Nofretete hielt Hoppel fest. So dunkel war es zu Hause noch nie gewesen.\n\nDa roch es nach Kakao und Zimt. Ganz oben am Baum glomm der Stern auf, erst schwach, dann immer heller – obwohl gar kein Strom da war. Sein Licht reichte genau bis zu den Kerzen auf dem Tisch.\n\nPapa zündete die Kerzen an. Plötzlich war das Zimmer golden und warm, viel schöner als mit Lampen. „So haben die Leute früher Weihnachten gefeiert“, sagte Mama.\n\nSie sangen „Stille Nacht“, und der Wind summte durch den Kamin mit. Draußen leuchtete der Schnee im Mondlicht.\n\nAls das Lied zu Ende war, gingen die Lichter wieder an. Aber alle wollten die Kerzen noch ein bisschen brennen lassen. Und unten am Baum klingelte eine kleine Glocke. Es war Zeit."
   }},
  {id:'weihnachten-herzblitz', occasion:'christmas', approved:true /* freigegeben von Peter am 02.11.2026, alle drei Stufen; en = freie amerikanische Übersetzung */,
   title:{en:"Herzblitz in the Snow", de:"Herzblitz im Schnee"},
   en:{
    1:"On Christmas Day, the magic racetrack was covered in snow. Herzblitz, the little race car, really, really wanted to drive.\n\n\"Careful!\" called Rocco. \"On ice, you slide way farther!\"\n\nHerzblitz took off – and when he hit the brakes, he slid and slid and slid, until he landed softly in a snowdrift. Ice has almost no friction, so it's really hard to stop.\n\nA warm breeze blew the snow off his hood. \"Start slower, brake sooner,\" it whispered.\n\nThe second time, Herzblitz drove very carefully. He braked early and stopped right on the finish line. Rocco cheered, and Nofretete clapped her mittens together.\n\nThat evening, Herzblitz parked under the Christmas tree, tired and happy. Big snowflakes were falling outside, and somewhere something giggled softly: \"Merry Christmas.\"",
    2:"On Christmas Day, Herzblitz and Rocco wanted to race on the snowy magic racetrack. \"Three, two, one – go!\"\n\nHerzblitz zoomed off. He was faster than ever before. Right before the big curve, he hit the brakes – but too late! On the ice he kept sliding and sliding, straight toward the edge of the track.\n\nNofretete covered her eyes. Then a warm breeze blew against Herzblitz's hood, and a snowdrift piled up right in front of him. Plop – Herzblitz landed softly in the fluffy snow. Nothing had happened.\n\n\"Ice has almost no friction,\" Rocco explained. \"You have to brake way earlier.\"\n\nIn the second race, Herzblitz started braking long before the curve. He only slid a tiny bit and made it through safely. Rocco won – but Herzblitz was proud.\n\nThat evening, he parked under the Christmas tree, tired and happy. And somewhere something giggled softly: \"Merry Christmas.\"",
    3:"On Christmas Day there was the big magic race – at night, on the frozen lake, with lanterns all along the edge. Herzblitz stood at the starting line, rumbling with excitement.\n\nRight after the start, there was a loud sound: \"Crrrack!\" Everyone froze. A thin crack ran across the ice. \"Back to the shore!\" yelled Rocco. \"Nice and slow!\"\n\nHerzblitz rolled back inch by inch, no gas and no brakes. A warm breeze blew beside him and gently pushed him along, until all four wheels were safe on the shore. Nobody fell into the water.\n\n\"Then let's race on the snowy road around the lake,\" Nofretete suggested. Snow has more friction than ice – so you can brake better.\n\nIt turned into the best race ever. In every curve, Herzblitz braked early and didn't slide one bit. He was the first to roll across the finish line, and everybody cheered.\n\nThat evening, he parked under the Christmas tree, tired and happy. Big snowflakes were falling outside, and somewhere something giggled softly: \"Merry Christmas.\""
   },
   de:{
    1:"Am ersten Weihnachtstag lag Schnee auf der Zauber-Rennbahn. Herzblitz, der kleine Rennwagen, wollte unbedingt fahren.\n\n„Vorsicht!“, rief Rocco. „Auf Eis rutscht man viel weiter!“\n\nHerzblitz fuhr los – und als er bremste, rutschte er und rutschte und rutschte, bis er sanft in einem Schneehaufen landete. Auf Eis gibt es fast keine Reibung, deshalb kommt man so schwer zum Stehen.\n\nEin warmer Wind pustete den Schnee von seiner Motorhaube. „Langsamer anfahren, früher bremsen“, flüsterte es.\n\nBeim zweiten Mal fuhr Herzblitz ganz vorsichtig. Er bremste früh und blieb genau an der Ziellinie stehen. Rocco jubelte, und Nofretete klatschte in die Fäustlinge.\n\nAm Abend parkte Herzblitz müde und glücklich unter dem Weihnachtsbaum. Draußen fielen dicke Flocken, und irgendwo kicherte es leise: „Frohe Weihnachten.“",
    2:"Am ersten Weihnachtstag wollten Herzblitz und Rocco auf der verschneiten Zauber-Rennbahn um die Wette fahren. „Drei, zwei, eins – los!“\n\nHerzblitz sauste davon. Er war schneller als je zuvor. Vor der großen Kurve bremste er – aber zu spät! Auf dem Eis rutschte er weiter und weiter, direkt auf den Rand der Bahn zu.\n\nNofretete hielt sich die Hände vor die Augen. Da wehte ein warmer Wind gegen Herzblitz' Motorhaube, und eine Schneewehe türmte sich genau vor ihm auf. Plumps – Herzblitz steckte sanft im weichen Schnee. Nichts war passiert.\n\n„Auf Eis gibt es fast keine Reibung“, erklärte Rocco. „Da musst du viel früher bremsen.“\n\nBeim zweiten Rennen bremste Herzblitz schon lange vor der Kurve. Er rutschte nur ein kleines Stück und fuhr sicher hindurch. Rocco gewann zwar – aber Herzblitz war stolz.\n\nAm Abend parkte er müde und glücklich unter dem Weihnachtsbaum. Und irgendwo kicherte es leise: „Frohe Weihnachten.“",
    3:"Am ersten Weihnachtstag war das große Zauber-Rennen – nachts, auf dem zugefrorenen See, mit Laternen am Rand. Herzblitz stand an der Startlinie und brummte aufgeregt.\n\nGleich nach dem Start hörte man ein lautes Knacken: „Krrrk!“ Alle blieben stehen. Ein feiner Riss zog sich über das Eis. „Zurück ans Ufer!“, rief Rocco. „Ganz langsam!“\n\nHerzblitz fuhr Stück für Stück zurück, ohne Gas und ohne Bremsen. Neben ihm wehte ein warmer Wind und schob ihn sanft, bis alle Räder sicher auf dem Ufer standen. Niemand war ins Wasser gefallen.\n\n„Dann fahren wir eben auf der Schneestraße um den See herum“, schlug Nofretete vor. Auf Schnee ist mehr Reibung als auf Eis – da kann man besser bremsen.\n\nEs wurde das schönste Rennen von allen. In jeder Kurve bremste Herzblitz früh und rutschte kein bisschen. Als Erster rollte er über die Ziellinie, und alle jubelten.\n\nAm Abend parkte er müde und glücklich unter dem Weihnachtsbaum. Draußen fielen dicke Flocken, und irgendwo kicherte es leise: „Frohe Weihnachten.“"
   }},
  {id:'geburtstag-hurra', occasion:'birthday', approved:true /* freigegeben von Peter am 02.11.2026, alle drei Stufen; en = freie amerikanische Übersetzung */,
   title:{en:"Guess Whose Birthday It Is?", de:"Wer hat heute Geburtstag?"},
   en:{
    1:"This morning, something was different. The wind was out and about super early, whispering in every corner.\n\nIt whispered to the goldfinch, who started practicing a song right away. It whispered to Rocco, who practiced his skateboard trick one more time. It even whispered to Mumifius, who was giggling with excitement.\n\n\"What's going on?\" asked Hoppel. But nobody would tell.\n\nThen all of a sudden, colorful leaves came flying through the air. They danced around and landed on the grass, and they spelled out a word: a giant \"HOORAY!\"\n\nGuess whose birthday it is today? Yours!\n\nAll of Pisolala's friends are thinking of you today. And the wind brought you something you can't see, but you can feel: Morvandel's words. \"You didn't make magic. You ARE magic.\"\n\nHappy birthday! And somewhere, very close, something is giggling with joy.",
    2:"This morning, the wind was out super early. It had a surprise all ready: a hundred colorful balloons, tied to the fence.\n\nBut then a gust came along. The strings came loose – and all the balloons flew away! High over the rooftops, smaller and smaller. Hoppel's ears drooped. \"Now the surprise is ruined.\"\n\nRocco, Mumifius, and the goldfinch stared sadly at the sky. But way up there, far away, something was happening. A warm breeze was zooming after the balloons and rounding them up – one by one, like a sheepdog with its sheep.\n\nSlowly, they floated back. And when they were right over the grass, they lined up to spell a word: a big, colorful \"HOORAY!\"\n\nGuess whose birthday it is today? Yours!\n\nAll of Pisolala's friends are thinking of you today. And the wind brought you Morvandel's words: \"You didn't make magic. You ARE magic.\" Happy birthday! And somewhere, very close, something is giggling with joy.",
    3:"This morning there was a note on the windowsill, written in sparkly letters: \"A treasure hunt! Clue number one: I have lots of feathers, but I can't fly. Where am I?\"\n\nNofretete and Hoppel thought hard. \"The pillow!\" Under the pillow was clue number two: \"I'm round, I'm bouncy, and at night the moon shines on me.\" \"The Moonlight Trampoline!\"\n\nThey ran out to the yard. It was shady under the trampoline, and something rustled in the leaves. Nofretete held her breath. Out came … the goldfinch, with clue number three in its beak: \"Go where Rocco loves to ride.\"\n\nRocco was waiting at the hill on his skateboard. \"You have to do the last part by yourself,\" he said. \"All the way up to the top.\" Nofretete climbed and climbed. At the top, the wind was whistling – but it was warm.\n\nAt the very top sat a little box. Inside was a note, and all their friends came up the hill to read it together:\n\nGuess whose birthday it is today? Yours! \"You didn't make magic. You ARE magic.\" Then everybody sang \"Happy Birthday.\" Happy birthday! And somewhere, very close, something is giggling with joy."
   },
   de:{
    1:"Heute Morgen war etwas anders. Der Wind war schon ganz früh unterwegs und flüsterte in allen Ecken.\n\nEr flüsterte mit dem Stieglitz, der sofort ein Lied übte. Er flüsterte mit Rocco, der seinen Skateboard-Trick noch einmal probte. Er flüsterte sogar mit Mumifius, der vor Aufregung kicherte.\n\n„Was ist denn los?“, fragte Hoppel. Aber niemand verriet etwas.\n\nDann flogen plötzlich bunte Blätter durch die Luft. Sie tanzten und legten sich auf die Wiese, und daraus wurde ein Wort: ein großes „Hurra!“.\n\nWeißt du, wer heute Geburtstag hat? Du!\n\nAlle Freunde von Pisolala haben heute an dich gedacht. Und der Wind hat dir etwas mitgebracht, das man nicht sehen, aber spüren kann: den Satz von Morvandel. „Du hast keine Magie gemacht. Du BIST Magie.“\n\nAlles Gute zum Geburtstag. Und irgendwo, ganz nah, kichert es vor Freude.",
    2:"Heute Morgen war der Wind schon ganz früh unterwegs. Er hatte eine Überraschung vorbereitet: hundert bunte Luftballons, festgebunden am Gartenzaun.\n\nDoch dann kam eine Böe. Die Schnüre lösten sich – und alle Ballons flogen davon! Hoch über die Dächer, immer kleiner. Hoppel ließ die Ohren hängen. „Jetzt ist die Überraschung kaputt.“\n\nRocco, Mumifius und der Stieglitz schauten traurig in den Himmel. Aber da oben, ganz weit weg, tat sich etwas. Ein warmer Wind sauste hinter den Ballons her und sammelte sie ein – einen nach dem anderen, wie ein Hirtenhund seine Schafe.\n\nLangsam schwebten sie zurück. Und als sie über der Wiese standen, ordneten sie sich zu einem Wort: ein großes, buntes „Hurra!“.\n\nWeißt du, wer heute Geburtstag hat? Du!\n\nAlle Freunde von Pisolala haben heute an dich gedacht. Und der Wind hat dir den Satz von Morvandel mitgebracht: „Du hast keine Magie gemacht. Du BIST Magie.“ Alles Gute zum Geburtstag. Und irgendwo, ganz nah, kichert es vor Freude.",
    3:"Heute Morgen lag ein Blatt auf dem Fensterbrett. Darauf stand in glitzernder Schrift: „Eine Schatzsuche! Erstes Rätsel: Ich habe viele Federn, aber ich kann nicht fliegen. Wo bin ich?“\n\nNofretete und Hoppel überlegten. „Das Kissen!“ Unter dem Kopfkissen lag das zweite Rätsel: „Ich bin rund, ich federe, und nachts scheint der Mond auf mich.“ – „Das Mondschein-Trampolin!“\n\nSie rannten in den Garten. Unter dem Trampolin war es schattig, und etwas raschelte im Laub. Nofretete hielt die Luft an. Heraus kam … der Stieglitz, mit dem dritten Rätsel im Schnabel: „Geh dorthin, wo Rocco am liebsten fährt.“\n\nAm Hügel wartete Rocco auf seinem Skateboard. „Das letzte Stück musst du allein schaffen“, sagte er, „den Hügel hinauf, bis ganz oben.“ Nofretete stieg und stieg. Oben pfiff der Wind, aber er war warm.\n\nOben stand eine kleine Kiste. Darin lag ein Zettel, und alle Freunde kamen von unten herauf, um ihn zusammen vorzulesen:\n\nWeißt du, wer heute Geburtstag hat? Du! „Du hast keine Magie gemacht. Du BIST Magie.“ Dann sangen alle ein Geburtstagslied. Alles Gute zum Geburtstag. Und irgendwo, ganz nah, kichert es vor Freude."
   }},
  {id:'alltag-stern-trampolin', approved:true /* freigegeben von Peter am 02.11.2026, alle drei Stufen; en = freie amerikanische Übersetzung */,
   title:{en:"The Star on the Trampoline", de:"Der Stern auf dem Trampolin"},
   en:{
    1:"On a clear night, something small and sparkly fell from the sky. It landed right on the Moonlight Trampoline.\n\nIt was a tiny star. \"I fell down,\" it squeaked, \"and I can't get back up by myself.\"\n\nNofretete and Hoppel climbed onto the trampoline. Right next to them, the trampoline bounced, even though nobody was standing there. Pisolala was jumping, too!\n\n\"We have to jump really high,\" said Nofretete. They counted by tens: 10 jumps, 20 jumps, 30 jumps. With every jump, the star went a little higher.\n\nOn jump number 40, a warm breeze blew up from below, and whoosh – the star flew back to its spot in the sky.\n\nFrom up there, it blinked three times. In star language, that means: thank you.\n\nNofretete lay down on the trampoline and looked up. She was tired from all that jumping. \"Good night, Pisolala.\" And the wind hummed a soft wind song.",
    2:"On a clear night, a tiny star fell onto the Moonlight Trampoline. \"I have to get back to the sky,\" it squeaked, \"before the moon goes down. Otherwise I won't find my spot again for a whole year!\"\n\nThe moon was already low over the rooftops. And thick clouds were rolling in from the west. \"Hurry!\" said Nofretete.\n\nShe jumped with Hoppel, and right next to them the trampoline bounced, even though nobody was standing there. They counted by tens: 10, 20, 30 jumps. But the clouds were getting closer, and the star was turning pale with worry.\n\n\"Take a deep breath,\" something whispered next to Nofretete, \"and jump with the light in your heart.\" On jump number 40, a warm breeze blew up from below, stronger than ever.\n\nWhoosh – the star flew up, right through a gap in the clouds, and landed in its spot. A second later, the clouds closed up.\n\nBut for just a moment, it blinked through three times: thank you. Nofretete lay down on the trampoline, all worn out. \"Good night, Pisolala.\" And the wind hummed a soft wind song.",
    3:"On a clear night, a tiny star fell from the sky – but not onto the trampoline. It fell right into the dark woods. Nofretete saw it sparkle and disappear between the trees.\n\nShe went into the woods with Hoppel and a lantern. The trees were tall, and the path split three times. \"Which way?\" she asked. Then fireflies showed up and flew ahead, like they were showing her the way.\n\nIn a clearing sat an owl. \"The star is in the moss by the creek,\" she said. \"But be careful, the creek is wide.\" Nofretete found a fallen tree trunk to use as a bridge and balanced across with her arms stretched out wide. A warm breeze helped her keep her balance.\n\nThere in the moss lay the star, very small and very tired. Nofretete carried it home in both hands, carefully, the whole way back.\n\nOn the Moonlight Trampoline they jumped: 10, 20, 30, 40 jumps. On jump number 40, a warm breeze blew up from below, and the star flew back to its spot.\n\nFrom up there, it blinked three times: thank you. Nofretete was so tired she fell asleep right there on the trampoline. \"Good night, Pisolala.\" And the wind tucked her in with a soft wind song."
   },
   de:{
    1:"In einer klaren Nacht fiel etwas Kleines, Glitzerndes vom Himmel. Es landete genau auf dem Mondschein-Trampolin.\n\nEs war ein winziger Stern. „Ich bin heruntergefallen“, piepste er, „und komme allein nicht mehr hinauf.“\n\nNofretete und Hoppel kletterten aufs Trampolin. Neben ihnen federte es, obwohl dort niemand stand. Pisolala hüpfte mit!\n\n„Wir müssen ganz hoch springen“, sagte Nofretete. Sie zählten in Zehnerschritten: 10 Sprünge, 20 Sprünge, 30 Sprünge. Bei jedem Sprung kam der Stern ein Stück höher.\n\nBeim 40. Sprung blies ein warmer Wind von unten, und hui – der Stern flog zurück an seinen Platz am Himmel.\n\nVon dort oben blinkte er dreimal. Das heißt in der Sternensprache: Danke.\n\nNofretete legte sich auf das Trampolin und schaute hinauf. Sie war müde vom vielen Springen. „Gute Nacht, Pisolala.“ Und der Wind summte ein leises Windlied.",
    2:"In einer klaren Nacht fiel ein winziger Stern auf das Mondschein-Trampolin. „Ich muss zurück an den Himmel“, piepste er, „bevor der Mond untergeht. Sonst finde ich meinen Platz erst in einem Jahr wieder!“\n\nDer Mond stand schon tief über den Dächern. Und von Westen zogen dicke Wolken heran. „Schnell!“, rief Nofretete.\n\nSie hüpften mit Hoppel, und neben ihnen federte es, obwohl dort niemand stand. Sie zählten in Zehnerschritten: 10, 20, 30 Sprünge. Aber die Wolken kamen näher, und der Stern wurde ganz blass vor Sorge.\n\n„Atme tief ein“, flüsterte es neben Nofretete, „und spring mit dem Licht in deinem Herzen.“ Beim 40. Sprung blies ein warmer Wind von unten, so stark wie noch nie.\n\nHui – der Stern flog hinauf, genau durch eine Lücke in den Wolken, und landete an seinem Platz. Gleich danach schoben sich die Wolken zu.\n\nDoch für einen Augenblick blinkte er noch dreimal hindurch: Danke. Nofretete legte sich müde aufs Trampolin. „Gute Nacht, Pisolala.“ Und der Wind summte ein leises Windlied.",
    3:"In einer klaren Nacht fiel ein winziger Stern vom Himmel – aber nicht auf das Trampolin, sondern mitten in den dunklen Wald. Nofretete sah ihn glitzernd zwischen den Bäumen verschwinden.\n\nMit Hoppel und einer Laterne ging sie in den Wald. Die Bäume waren hoch, und der Weg teilte sich dreimal. „Wo lang?“, fragte sie. Da tauchten Glühwürmchen auf und flogen voraus, als wollten sie den Weg zeigen.\n\nAn einer Lichtung saß eine Eule. „Der Stern liegt im Moos am Bach“, sagte sie. „Aber pass auf, der Bach ist breit.“ Nofretete fand einen umgestürzten Baumstamm als Brücke und balancierte hinüber, die Arme weit ausgestreckt. Ein warmer Wind hielt sie dabei im Gleichgewicht.\n\nIm Moos lag der Stern, ganz klein und müde. Nofretete trug ihn vorsichtig in beiden Händen nach Hause, den ganzen Weg zurück.\n\nAuf dem Mondschein-Trampolin hüpften sie: 10, 20, 30, 40 Sprünge. Beim 40. Sprung blies es warm von unten, und der Stern flog zurück an seinen Platz.\n\nVon dort oben blinkte er dreimal: Danke. Nofretete war so müde, dass sie gleich auf dem Trampolin einschlief. „Gute Nacht, Pisolala.“ Und der Wind deckte sie mit einem leisen Windlied zu."
   }},
  {id:'alltag-skarabaeus', approved:true /* freigegeben von Peter am 02.11.2026, alle drei Stufen; en = freie amerikanische Übersetzung */,
   title:{en:"The Scarab Who Couldn't Sleep", de:"Der Skarabäus kann nicht schlafen"},
   en:{
    1:"The talking scarab beetle was lying on his back, kicking his little legs. \"I can't sleep,\" he sighed. \"It's so loud in my head.\"\n\nNofretete sat down next to him. \"What's so loud?\"\n\n\"Everything,\" said the scarab. \"What's happening tomorrow. What happened today. Whether I did everything right.\"\n\nNofretete just listened, and the warm breeze listened, too. Sometimes your head gets quieter when somebody listens.\n\nThen the breeze hummed a song, very slowly, like waves at the beach. In. And out. In. And out.\n\nThe scarab's little legs got calmer. \"Will you stay a little longer?\" he mumbled. \"We'll stay,\" said Nofretete.\n\nSoon the scarab was snoring very softly. Nofretete yawned. \"Good night, Pisolala.\" And somewhere, something giggled: \"Good night.\"",
    2:"The talking scarab beetle couldn't sleep. \"There's a noise,\" he whispered. \"Do you hear it? Tap. Tap. Tap.\"\n\nNofretete listened. Sure enough: Tap. Tap. Tap. It was coming from the window. Outside, a long dark arm was swinging back and forth.\n\nThe scarab hid under Hoppel. Nofretete gathered up her courage. It got warm next to her, and it smelled like cocoa and cinnamon. \"Go take a look,\" something whispered. \"Together.\"\n\nShe pulled back the curtain. The long arm was – a branch from the apple tree, swinging against the glass in the wind. Tap. Tap. \"It's just a branch!\" Nofretete laughed.\n\nShe opened the window a crack and tied the branch to the gutter with her hair tie. A warm breeze helped. Now everything was quiet.\n\nThe scarab crawled out from under Hoppel. \"Will you stay a little longer?\" he mumbled. \"We'll stay.\" Soon he was snoring very softly. \"Good night, Pisolala.\" And somewhere, something giggled: \"Good night.\"",
    3:"The talking scarab beetle couldn't sleep. \"If only I were tired,\" he sighed. Then a warm breeze blew through the room, and a huge leaf floated in – as big as a boat.\n\n\"Hop in,\" something whispered. Nofretete, Hoppel, and the scarab climbed onto the leaf. It carried them out the window and set them down gently on the river behind the house.\n\nThey drifted along under the stars, past sleeping ducks and glowing fireflies. But then they heard a rushing sound that kept getting louder. Up ahead was a waterfall!\n\n\"Hold on!\" yelled Nofretete. The warm breeze blew hard from the side, and the leaf turned, little by little, until it slid up onto the bank – far away from the waterfall. There was a soft bed of moss.\n\nThey lay down in it. Above them the stars twinkled, and now the waterfall rushed along nice and steady, like a lullaby. In. And out. In. And out.\n\nThe scarab yawned and fell asleep. So did Nofretete. When she woke up, she was in her own bed. There was just one big leaf lying on her blanket. \"Good night, Pisolala,\" she whispered. And somewhere, something giggled: \"Good night.\""
   },
   de:{
    1:"Der sprechende Skarabäus lag auf dem Rücken und strampelte mit den Beinchen. „Ich kann nicht schlafen“, seufzte er. „In meinem Kopf ist es so laut.“\n\nNofretete setzte sich zu ihm. „Was ist denn so laut?“\n\n„Alles“, sagte der Skarabäus. „Was morgen ist. Was heute war. Ob ich alles richtig gemacht habe.“\n\nNofretete hörte einfach zu, und der warme Wind hörte auch zu. Manchmal wird der Kopf leiser, wenn jemand zuhört.\n\nDann summte der Wind ein Lied, ganz langsam, wie Wellen am Strand. Ein. Und aus. Ein. Und aus.\n\nDie Beinchen des Skarabäus wurden ruhiger. „Bleibt ihr noch ein bisschen?“, murmelte er. „Wir bleiben“, sagte Nofretete.\n\nBald schnarchte der Skarabäus ganz leise. Nofretete gähnte. „Gute Nacht, Pisolala.“ Und irgendwo kicherte es: „Gute Nacht.“",
    2:"Der sprechende Skarabäus konnte nicht schlafen. „Da ist ein Geräusch“, flüsterte er. „Hörst du? Tock. Tock. Tock.“\n\nNofretete lauschte. Tatsächlich: Tock. Tock. Tock. Es kam vom Fenster. Draußen bewegte sich ein langer dunkler Arm hin und her.\n\nDer Skarabäus versteckte sich unter Hoppel. Nofretete nahm ihren Mut zusammen. Neben ihr wurde es warm, und es roch nach Kakao und Zimt. „Schau nach“, flüsterte es. „Zusammen.“\n\nSie zog den Vorhang auf. Der lange Arm war – ein Ast vom Apfelbaum, den der Wind gegen die Scheibe schaukelte. Tock. Tock. „Nur ein Ast!“, lachte Nofretete.\n\nSie öffnete das Fenster einen Spalt und band den Ast mit ihrem Haargummi an der Regenrinne fest. Ein warmer Wind half dabei. Jetzt war es still.\n\nDer Skarabäus kroch unter Hoppel hervor. „Bleibt ihr noch ein bisschen?“, murmelte er. „Wir bleiben.“ Bald schnarchte er ganz leise. „Gute Nacht, Pisolala.“ Und irgendwo kicherte es: „Gute Nacht.“",
    3:"Der sprechende Skarabäus konnte nicht schlafen. „Wenn ich doch nur müde wäre“, seufzte er. Da wehte ein warmer Wind durchs Zimmer, und ein großes Blatt schwebte herein, so groß wie ein Boot.\n\n„Steigt ein“, flüsterte es. Nofretete, Hoppel und der Skarabäus kletterten auf das Blatt. Es trug sie zum Fenster hinaus und setzte sie sanft auf den Fluss hinter dem Haus.\n\nSie trieben unter den Sternen dahin, vorbei an schlafenden Enten und leuchtenden Glühwürmchen. Doch dann hörten sie ein Rauschen, das immer lauter wurde. Vor ihnen war ein Wasserfall!\n\n„Festhalten!“, rief Nofretete. Der warme Wind blies kräftig von der Seite, und das Blatt drehte sich, Stück für Stück, bis es ans Ufer glitt – weit vor dem Wasserfall. Dort lag ein weiches Moosbett.\n\nSie legten sich hinein. Über ihnen funkelten die Sterne, und der Wasserfall rauschte jetzt ganz gleichmäßig, wie ein Wiegenlied. Ein. Und aus. Ein. Und aus.\n\nDer Skarabäus gähnte und schlief ein. Nofretete auch. Als sie aufwachte, lag sie in ihrem Bett. Nur ein großes Blatt lag auf der Decke. „Gute Nacht, Pisolala“, flüsterte sie. Und irgendwo kicherte es: „Gute Nacht.“"
   }},
  {id:'alltag-rocco-berg', approved:true /* freigegeben von Peter am 02.11.2026, alle drei Stufen; en = freie amerikanische Übersetzung */,
   title:{en:"Rocco and the Steep Hill", de:"Rocco und der steile Berg"},
   en:{
    1:"Rocco stood at the top of the hill with his skateboard. Everybody was waiting at the bottom. But Rocco didn't go.\n\n\"The hill is so steep,\" he said quietly. \"What if I fall?\"\n\nNofretete stood next to him. \"You don't have to,\" she said. \"But if you want to, we can try it together.\"\n\nA warm breeze ruffled Rocco's fur. \"Take a deep breath,\" it whispered, \"and think of the lantern in your heart.\"\n\nRocco breathed in and out. Then he rolled off – just a little way at first, then a little more. He wobbled once, but he didn't fall. And when he got to the bottom, he threw both paws in the air.\n\n\"I was scared and I did it anyway!\" he shouted. At school, that's called being a *risk-taker*: you try something new, even when it's a little hard.\n\nThat evening, Rocco told everybody about it three times. And every time, the wind giggled along.",
    2:"Rocco stood at the top of the hill with his skateboard. At the bottom of the path was a giant puddle, and he had to steer right around it.\n\n\"What if I ride straight into it?\" he asked quietly. \"Then you'll get wet,\" said Nofretete. \"But it won't hurt.\"\n\nA warm breeze ruffled Rocco's fur. \"Take a deep breath,\" it whispered, \"and think of the lantern in your heart.\" Rocco breathed in – and took off.\n\nHe went faster. The puddle got closer. The board wobbled, once to the left, once to the right. Nofretete held her breath.\n\nAt the very last second, Rocco leaned to the side – and zoomed past the puddle by a whisker. Only a few drops splashed his tail. \"I did it!\" he cheered.\n\nAt school, that's called being a *risk-taker*: you try something, even when it's a little hard. That evening, Rocco told everybody about it three times. And every time, the wind giggled along.",
    3:"The skate park had a new ramp – the tallest one of all. Everybody watched as Rocco stood at the top with his helmet on. \"That's really high,\" he whispered.\n\nOn his first try, he took off, got scared, and jumped off right before the ramp. He landed in the soft grass. \"I'm okay!\" he called, straightening his helmet.\n\nOn his second try, he made it farther, but at the edge of the ramp he chickened out again. A few kids giggled. Rocco's ears drooped.\n\nNofretete walked over to him. \"You don't have to make it,\" she said. \"But you've already tried twice. That's brave.\" A warm breeze ruffled his fur. \"Take a deep breath,\" it whispered, \"and think of the lantern in your heart.\"\n\nOn his third try, Rocco took off without stopping. He shot up the ramp, flew through the air for a split second – and landed safely on all four wheels. The whole skate park cheered.\n\n\"I was scared and I did it anyway!\" he shouted. That's a real *risk-taker*. That evening, Rocco told everybody about it three times. And every time, the wind giggled along."
   },
   de:{
    1:"Rocco stand oben am Hügel mit seinem Skateboard. Unten warteten alle. Aber Rocco fuhr nicht los.\n\n„Der Berg ist so steil“, sagte er leise. „Was ist, wenn ich hinfalle?“\n\nNofretete stellte sich neben ihn. „Du musst nicht“, sagte sie. „Aber wenn du willst, probieren wir es zusammen.“\n\nEin warmer Wind strich Rocco über das Fell. „Atme tief ein“, flüsterte es, „und denk an die Laterne in deinem Herzen.“\n\nRocco atmete ein und wieder aus. Dann fuhr er los – erst ein kleines Stück, dann noch ein Stück. Einmal wackelte er, aber er fiel nicht. Und unten angekommen riss er beide Pfoten hoch.\n\n„Ich hatte Angst und hab’s trotzdem gemacht!“, rief er. In der Schule nennt man das *Risk-taker*: Man probiert etwas Neues, auch wenn es ein bisschen schwer ist.\n\nAm Abend erzählte Rocco es allen dreimal. Und der Wind kicherte jedes Mal mit.",
    2:"Rocco stand oben am Hügel mit seinem Skateboard. Unten am Weg war eine riesige Pfütze, und er musste genau daran vorbeilenken.\n\n„Was ist, wenn ich hineinfahre?“, fragte er leise. „Dann wirst du nass“, sagte Nofretete. „Aber wehtun tut es nicht.“\n\nEin warmer Wind strich Rocco über das Fell. „Atme tief ein“, flüsterte es, „und denk an die Laterne in deinem Herzen.“ Rocco atmete ein – und fuhr los.\n\nEr wurde schneller. Die Pfütze kam näher. Das Board wackelte, einmal nach links, einmal nach rechts. Nofretete hielt den Atem an.\n\nIm letzten Moment lehnte Rocco sich zur Seite – und sauste haarscharf an der Pfütze vorbei. Nur ein paar Spritzer trafen seinen Schwanz. „Ich hab's geschafft!“, jubelte er.\n\nIn der Schule nennt man das *Risk-taker*: Man probiert etwas, auch wenn es ein bisschen schwer ist. Am Abend erzählte Rocco es allen dreimal. Und der Wind kicherte jedes Mal mit.",
    3:"Im Skatepark gab es eine neue Rampe, die höchste von allen. Alle schauten zu, als Rocco mit seinem Helm oben stand. „Das ist wirklich hoch“, flüsterte er.\n\nBeim ersten Versuch fuhr er los, bekam Angst und sprang kurz vor der Rampe ab. Er landete im weichen Gras. „Alles gut“, rief er und rückte den Helm zurecht.\n\nBeim zweiten Versuch kam er weiter, aber oben an der Kante bremste er wieder ab. Einige Zuschauer kicherten. Rocco ließ die Ohren hängen.\n\nNofretete ging zu ihm. „Du musst es nicht schaffen“, sagte sie. „Aber du hast es schon zweimal probiert. Das ist mutig.“ Ein warmer Wind strich ihm über das Fell. „Atme tief ein“, flüsterte es, „und denk an die Laterne in deinem Herzen.“\n\nBeim dritten Versuch fuhr Rocco los, ohne zu zögern. Er schoss die Rampe hinauf, flog einen kleinen Moment durch die Luft – und landete sicher auf allen vier Rollen. Der ganze Skatepark jubelte.\n\n„Ich hatte Angst und hab's trotzdem gemacht!“, rief er. Das ist ein echter *Risk-taker*. Am Abend erzählte Rocco es allen dreimal. Und der Wind kicherte jedes Mal mit."
   }},
  {id:'alltag-pfuetze', approved:true /* freigegeben von Peter am 02.11.2026, alle drei Stufen; en = freie amerikanische Übersetzung */,
   title:{en:"The Sad Little Puddle", de:"Die Pfütze, die traurig war"},
   en:{
    1:"After the rain, there was a big puddle in the yard. It was very still and very gray.\n\n\"Nobody likes me,\" it gurgled. \"Everybody just walks around me.\"\n\nNofretete crouched down. In the puddle she could see the sky, the clouds, and her own face. \"You're a mirror!\" she said. \"You bring the sky right down to the ground!\"\n\nThen a warm breeze blew across the water, and little ripples sparkled like stars. The clouds in the puddle drifted on, and the sun came out.\n\nThe puddle turned bright and blue. \"I never knew that,\" it gurgled quietly.\n\nHoppel really, really wanted to jump in. Nofretete laughed. \"Just once, and be careful!\" Splash!\n\nThe puddle laughed along – and somewhere in the wind, something giggled, too.",
    2:"After the rain, there was a big puddle in the yard. Nofretete had just discovered that it showed the sky like a mirror. The puddle was so happy.\n\nThen the big dog from next door came running, ears flying, straight at the puddle! \"Help!\" gurgled the puddle. \"If he jumps in, I'll splash everywhere, and then I'll be gone!\"\n\nNofretete stood in front of the puddle. \"Stop!\" she called. But the dog was fast. Then a warm breeze blew a stick right in front of the dog's paws.\n\nThe dog stopped, sniffed the stick, and totally forgot about the puddle. He trotted off happily with the stick.\n\n\"Thank you,\" gurgled the puddle. \"I thought that was the end of me.\" And then it started to drizzle, and the puddle got even a little bigger.\n\nHoppel got to hop in once, very carefully. Splash! The puddle laughed along – and somewhere in the wind, something giggled, too.",
    3:"After the rain, there was a big puddle in the yard. But then the sun came out, hot and bright, and the puddle got smaller and smaller. \"I'm disappearing!\" it cried, scared.\n\nNofretete knelt down. \"You're not disappearing,\" she said. \"You're changing. The water turns into vapor, rises up, and becomes a cloud. We learned that.\"\n\nAnd sure enough: the puddle rose into the sky as a fine mist. A warm breeze carried it higher and higher, until it was a little white cloud.\n\nNow the cloud traveled over the town. It saw the rooftops, the river, and the kids at the playground. Over the mountains it met other clouds, and together they grew big and gray. Thunder rumbled – the cloud got scared. But the wind whispered, \"That's just the sound clouds make when they want to go home.\"\n\nThen it started to rain. Drop by drop, the cloud fell back down – right into the yard, into the very same dip as before.\n\n\"I'm back!\" gurgled the puddle. \"And I've been to the mountains!\" Hoppel hopped in for joy. Splash! The puddle laughed along – and somewhere in the wind, something giggled, too."
   },
   de:{
    1:"Nach dem Regen lag im Hof eine große Pfütze. Sie war ganz still und ganz grau.\n\n„Niemand mag mich“, blubberte sie. „Alle laufen um mich herum.“\n\nNofretete hockte sich hin. In der Pfütze sah sie den Himmel, die Wolken und ihr eigenes Gesicht. „Du bist ja ein Spiegel“, staunte sie. „Du zeigst uns den Himmel unten auf der Erde!“\n\nDa wehte ein warmer Wind über das Wasser, und kleine Wellen glitzerten wie Sterne. Die Wolken in der Pfütze zogen weiter, und die Sonne kam heraus.\n\nDie Pfütze wurde hell und blau. „Das wusste ich gar nicht“, blubberte sie leise.\n\nHoppel wollte unbedingt hineinspringen. Nofretete lachte. „Nur einmal, und ganz vorsichtig!“ Platsch!\n\nDie Pfütze lachte mit – und irgendwo im Wind kicherte es auch.",
    2:"Nach dem Regen lag im Hof eine große Pfütze. Nofretete hatte gerade entdeckt, dass sie wie ein Spiegel den Himmel zeigte. Die Pfütze freute sich.\n\nDa kam der große Nachbarshund angerannt, mit fliegenden Ohren, direkt auf die Pfütze zu! „Hilfe“, blubberte die Pfütze. „Wenn er hineinspringt, spritze ich in alle Richtungen, und dann bin ich weg!“\n\nNofretete stellte sich vor die Pfütze. „Halt!“, rief sie. Aber der Hund war schnell. Da wehte ein warmer Wind und trug einen Stock vor die Pfoten des Hundes.\n\nDer Hund blieb stehen, schnüffelte am Stock und vergaß die Pfütze ganz. Glücklich trug er den Stock davon.\n\n„Danke“, blubberte die Pfütze. „Ich dachte, gleich ist es aus mit mir.“ Und dann fing es an zu nieseln, und die Pfütze wurde sogar noch ein bisschen größer.\n\nHoppel durfte einmal ganz vorsichtig hineinhüpfen. Platsch! Die Pfütze lachte mit – und irgendwo im Wind kicherte es auch.",
    3:"Nach dem Regen lag im Hof eine große Pfütze. Doch dann kam die Sonne heraus, heiß und hell, und die Pfütze wurde kleiner und kleiner. „Ich verschwinde!“, rief sie ängstlich.\n\nNofretete kniete sich hin. „Du verschwindest nicht“, sagte sie. „Du verwandelst dich. Das Wasser wird zu Dampf, steigt auf und wird eine Wolke. Das haben wir gelernt.“\n\nUnd wirklich: Die Pfütze stieg als feiner Dunst in den Himmel. Ein warmer Wind trug sie höher, bis sie eine kleine weiße Wolke war.\n\nNun reiste die Wolke über die Stadt. Sie sah die Dächer, den Fluss, die Kinder auf dem Spielplatz. Über den Bergen traf sie andere Wolken, die wurden zusammen groß und grau. Ein Donner grollte – die Wolke erschrak. Aber der Wind flüsterte: „Das ist nur der Klang, wenn Wolken nach Hause wollen.“\n\nDann fing es an zu regnen. Tropfen für Tropfen fiel die Wolke zurück – genau in den Hof, in dieselbe Mulde wie vorher.\n\n„Ich bin wieder da!“, blubberte die Pfütze. „Und ich war in den Bergen!“ Hoppel hüpfte vor Freude hinein. Platsch! Die Pfütze lachte mit – und irgendwo im Wind kicherte es auch."
   }},
  {id:'alltag-brief-morvandel', approved:true /* freigegeben von Peter am 02.11.2026, alle drei Stufen; en = freie amerikanische Übersetzung */,
   title:{en:"A Letter to Morvandel", de:"Ein Brief an Morvandel"},
   en:{
    1:"Nofretete had a question she just couldn't stop thinking about. So she wrote a letter to Morvandel the wizard.\n\n\"Dear Morvandel, I think everyone should be allowed to have a pet. One reason is that animals comfort you. For example, Hoppel always snuggles with me when I'm sad. That's why I think everybody needs an animal to love. What do you think?\"\n\nShe folded the letter and put it on the windowsill. A warm breeze picked it up and carried it off, high over the rooftops.\n\nThe next morning, there was a leaf on the windowsill. On it, in sparkly writing: \"Dear Nofretete, your letter convinced me. It has an opinion, a reason, an example, and at the end, the opinion again. That's exactly how you convince someone.\"\n\nAnd underneath, very small: \"P.S. Hoppel is a very good example.\"\n\nNofretete gave Hoppel a big squeeze. And at the window, something giggled softly.",
    2:"Nofretete wrote a letter to Morvandel the wizard: \"Dear Morvandel, I think everyone should be allowed to have a pet. One reason is that animals comfort you. For example, Hoppel always snuggles with me when I'm sad. That's why I think everybody needs an animal to love. What do you think?\"\n\nShe put the letter on the windowsill. But a sneaky gust of wind – not the warm one – grabbed it and blew it the wrong way, into the neighbors' yard, way up in the poplar tree.\n\n\"Oh no! Now it'll never get there!\" Nofretete waited a whole day. No answer came. By evening, she was sad.\n\nThen it smelled like cocoa and cinnamon. Outside, the poplar rustled, and a warm breeze pulled the letter loose from the branches. It carried it high over the rooftops – the right way this time.\n\nThe next morning, there was a leaf on the windowsill, with sparkly writing: \"Dear Nofretete, your letter took a little detour, but it convinced me. An opinion, a reason, an example, and at the end, the opinion again – that's exactly how you convince someone.\"\n\nAnd underneath, very small: \"P.S. Hoppel is a very good example.\" Nofretete gave Hoppel a big squeeze. And at the window, something giggled softly.",
    3:"Nofretete had written a letter to Morvandel the wizard: \"I think everyone should be allowed to have a pet. One reason is that animals comfort you. For example, Hoppel always snuggles with me when I'm sad. That's why I think everybody needs an animal to love.\"\n\n\"I want to deliver it myself,\" she said. So the warm breeze folded the letter into a giant paper airplane. Nofretete and Hoppel climbed aboard, and whoosh – they flew over the rooftops, over the river, up into the clouds.\n\nMorvandel's tower stood right in the middle of the clouds. The stairs to his door were made of fog. \"Can you walk on that?\" Nofretete asked. She put one foot down carefully – and the fog held her up, step by step.\n\nAt the top, Morvandel opened the door. He read the letter very slowly and nodded. \"You have an opinion, a reason, an example, and at the end, the opinion again,\" he said. \"That's how you convince someone. And you convinced me.\"\n\nThen he bent down to Hoppel. \"And you are a very good example.\" Hoppel wiggled his ears proudly.\n\nThe paper airplane flew them home as the sun went down. Nofretete fell asleep right away. In the morning, there was a leaf on the windowsill, with sparkly writing: \"Come back soon.\" And at the window, something giggled softly."
   },
   de:{
    1:"Nofretete hatte eine Frage, die sie nicht loslassen wollte. Also schrieb sie einen Brief an den Zauberer Morvandel.\n\n„Lieber Morvandel, ich finde, jeder sollte ein Haustier haben dürfen. Ein Grund ist, dass Tiere einen trösten. Zum Beispiel kuschelt Hoppel immer mit mir, wenn ich traurig bin. Deshalb finde ich: Jeder braucht ein Tier zum Liebhaben. Was meinst du?“\n\nSie faltete den Brief und legte ihn aufs Fensterbrett. Ein warmer Wind nahm ihn mit, hoch über die Dächer.\n\nAm nächsten Morgen lag ein Blatt auf dem Fensterbrett. Darauf stand in glitzernder Schrift: „Liebe Nofretete, dein Brief hat mich überzeugt. Er hat eine Meinung, einen Grund, ein Beispiel und am Ende noch einmal die Meinung. Genau so überzeugt man jemanden.“\n\nUnd darunter, ganz klein: „PS: Hoppel ist ein sehr gutes Beispiel.“\n\nNofretete drückte Hoppel ganz fest. Und am Fenster kicherte es leise.",
    2:"Nofretete schrieb einen Brief an den Zauberer Morvandel: „Lieber Morvandel, ich finde, jeder sollte ein Haustier haben dürfen. Ein Grund ist, dass Tiere einen trösten. Zum Beispiel kuschelt Hoppel immer mit mir, wenn ich traurig bin. Deshalb finde ich: Jeder braucht ein Tier zum Liebhaben. Was meinst du?“\n\nSie legte den Brief aufs Fensterbrett. Doch ein frecher Windstoß – nicht der warme – riss ihn mit und wehte ihn in die falsche Richtung, direkt in den Garten der Nachbarn, hoch oben in die Pappel.\n\n„Oh nein! Jetzt kommt er nie an!“ Nofretete wartete einen ganzen Tag. Kein Brief kam zurück. Am Abend war sie traurig.\n\nDa roch es nach Kakao und Zimt. Draußen raschelte die Pappel, und ein warmer Wind löste den Brief aus den Zweigen. Er trug ihn hoch über die Dächer, diesmal in die richtige Richtung.\n\nAm nächsten Morgen lag ein Blatt auf dem Fensterbrett, in glitzernder Schrift: „Liebe Nofretete, dein Brief hat einen kleinen Umweg gemacht, aber er hat mich überzeugt. Meinung, Grund, Beispiel und am Ende noch einmal die Meinung – genau so überzeugt man jemanden.“\n\nUnd ganz klein darunter: „PS: Hoppel ist ein sehr gutes Beispiel.“ Nofretete drückte Hoppel ganz fest. Und am Fenster kicherte es leise.",
    3:"Nofretete hatte einen Brief an den Zauberer Morvandel geschrieben: „Ich finde, jeder sollte ein Haustier haben dürfen. Ein Grund ist, dass Tiere einen trösten. Zum Beispiel kuschelt Hoppel immer mit mir, wenn ich traurig bin. Deshalb finde ich: Jeder braucht ein Tier zum Liebhaben.“\n\n„Ich will ihn selbst hinbringen“, sagte sie. Da faltete der warme Wind den Brief zu einem großen Papierflieger. Nofretete und Hoppel stiegen auf, und hui – flogen sie über die Dächer, über den Fluss, hinauf zu den Wolken.\n\nMorvandels Turm stand mitten in den Wolken. Die Treppe zu seiner Tür war aus Nebel. „Kann man darauf gehen?“, fragte Nofretete. Sie setzte vorsichtig einen Fuß darauf – und der Nebel trug sie, Stufe für Stufe.\n\nOben öffnete Morvandel die Tür. Er las den Brief ganz langsam und nickte. „Du hast eine Meinung, einen Grund, ein Beispiel und am Ende noch einmal die Meinung“, sagte er. „So überzeugt man jemanden. Du hast mich überzeugt.“\n\nDann beugte er sich zu Hoppel hinunter. „Und du bist ein sehr gutes Beispiel.“ Hoppel wackelte stolz mit den Ohren.\n\nDer Papierflieger brachte sie nach Hause, als die Sonne unterging. Nofretete schlief sofort ein. Am Morgen lag ein Blatt auf dem Fensterbrett, mit glitzernder Schrift: „Komm bald wieder.“ Und am Fenster kicherte es leise."
   }}
];

/** Approved stories that can be told in this language within the excitement limit. */
export function storiesUsable(stories, lang, cap){
  return stories.filter(s=>s.approved && s[lang] && Object.keys(s[lang]).some(l=>+l<=cap));
}

/** The story for now. ctx: {lang, cap, theme (themeNow), birthday (true on the day), read (ids, oldest first)}.
    Returns a story or null. */
export function storyNext(stories, ctx){
  const read=Array.isArray(ctx.read)?ctx.read:[];
  const all=storiesUsable(stories, ctx.lang, ctx.cap);
  const now=s=>s.occasion==='birthday' ? !!ctx.birthday : s.occasion===ctx.theme;
  const unread=s=>!read.includes(s.id);
  if(ctx.birthday){ const b=all.find(s=>s.occasion==='birthday' && unread(s)); if(b) return b; }
  if(ctx.theme){ const t=all.find(s=>s.occasion===ctx.theme && unread(s)); if(t) return t; }
  const plain=all.find(s=>!s.occasion && unread(s)); if(plain) return plain;
  const allowed=all.filter(s=>!s.occasion || now(s));
  const pool=allowed.length ? allowed : all;                     // no other story at all: an occasion story is better than none
  if(!pool.length) return null;
  const rank=s=>{ const i=read.lastIndexOf(s.id); return i<0 ? -1 : i; };
  return pool.slice().sort((a,b)=>rank(a)-rank(b))[0];           // never read first, then the one read longest ago
}

/** Remember a story as read: it moves to the end (newest). */
export function storyMarkRead(read, id){
  return (Array.isArray(read)?read:[]).filter(x=>x!==id).concat(id);
}
